import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with expanded line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 10,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 0,
  });
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'c-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice normalizes customer ID with whitespace', () => {
  const r = createInvoice({
    customerId: ' c-002 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for an unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date formats', () => {
  const testCases = ['2026-10-7', '2026-1-07', '26-10-07', '10-07-2026', 'not-a-date', ''];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
