  assert.equal(r2.ok, true);
  assert.deepEqual(r2.value.voucher, { code: 'SUMMER10', amount: 10000 });
});

test('applyVoucher reduces total in invoiceTotals', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totalsWithout = invoiceTotals(r1.value);
  const r2 = applyVoucher(r1.value, { code: 'SUMMER10', amount: 50000 });
  const totalsWith = invoiceTotals(r2.value);
  assert.equal(totalsWith.total, totalsWithout.total - 50000);
});

test('applyVoucher clamped total does not go below zero', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totalsWithout = invoiceTotals(r1.value);
  const r2 = applyVoucher(r1.value, { code: 'HUGE', amount: totalsWithout.total + 1000000 });
  const totalsWith = invoiceTotals(r2.value);
  assert.equal(totalsWith.total, 0);
});

test('applyVoucher reports NOT_DRAFT for issued invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const r3 = applyVoucher(r2.value, { code: 'SUMMER10', amount: 10000 });
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'NOT_DRAFT');
});

test('applyVoucher reports VOUCHER_EXISTS if one is already applied', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const r2 = applyVoucher(r1.value, { code: 'SUMMER10', amount: 10000 });
  const r3 = applyVoucher(r2.value, { code: 'ANOTHER', amount: 5000 });
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'VOUCHER_EXISTS');
});

test('applyVoucher reports AMOUNT_INVALID for non-integer amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const testCases = [0, -100, 1.5, 'abc', null, undefined];
  for (const amount of testCases) {
    const r2 = applyVoucher(r1.value, { code: 'TEST', amount });
    assert.equal(r2.ok, false);
    assert.equal(r2.error, 'AMOUNT_INVALID', `for amount "${amount}"`);
  }
});

test('applyVoucher does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const original = { ...r1.value };
  applyVoucher(r1.value, { code: 'SUMMER10', amount: 10000 });
  assert.deepEqual(r1.value, original);
});

test('invoiceTotals with voucher applied', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
