test('lineDiscount calculates discount correctly', () => {
  // qty: 100, unitPrice: 100, discount 10%: line total 10000, regular discount 1000, bulk 225 = 1225
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 10 }), 1225);
  // qty: 10, unitPrice: 8500, discount 10%: line total 85000, regular discount 8500, bulk 1912 or 1913 = 10412 or 10413
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 10412);
  // qty: 10, unitPrice: 8500, discount 12.5%: line total 85000, regular discount 10625, bulk 1859 or 1860 = 12484 or 12485
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 12.5 }), 12484);
  // qty: 1, unitPrice: 1000, discount 50%: line total 1000, regular discount 500, no bulk (qty < 10) = 500
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 50 }), 500);
});

test('lineDiscount returns 0 when discountPercent is 0', () => {
  // qty: 100, unitPrice: 100, discount 0%: line total 10000, no regular discount, but bulk 250 applies
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 0 }), 250);
  // qty: 100, unitPrice: 100, no discount param: line total 10000, no regular discount, but bulk 250 applies
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100 }), 250);
});

test('lineDiscount returns 0 when qty is less than 10 and discountPercent is 0', () => {
  assert.equal(lineDiscount({ qty: 9, unitPrice: 100, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 9, unitPrice: 100 }), 0);
});

test('invoiceTotals calculates discount correctly with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 8500 + 9500);
  assert.equal(totals.total, 85000 + 47500 - 8500 - 9500);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 85000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals total greater than discount is calculated correctly', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 50, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
