  const r2 = applyVoucher(r1.value, { code: 'HUGE', amount: totalsWithout.total + 1000000 });
  const totalsWith = invoiceTotals(r2.value);
  assert.equal(totalsWith.total, 0);
});

test('applyVoucher reports NOT_DRAFT for issued invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
