  const r3 = applyVoucher(r2.value, { code: 'SUMMER10', amount: 10000 });
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'NOT_DRAFT');
});

test('applyVoucher reports VOUCHER_EXISTS if one is already applied', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
