  const r3 = applyVoucher(r2.value, { code: 'ANOTHER', amount: 5000 });
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'VOUCHER_EXISTS');
});

test('applyVoucher reports AMOUNT_INVALID for non-integer amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
