});

test('lineDiscount calculates discount correctly', () => {
  // qty: 100, unitPrice: 100, discount 10%: line total 10000, regular discount 1000, bulk 225 = 1225
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 10 }), 1225);
  // qty: 10, unitPrice: 8500, discount 10%: line total 85000, regular discount 8500, bulk 1912 or 1913 = 10412 or 10413
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 10412);
  // qty: 10, unitPrice: 8500, discount 12.5%: line total 85000, regular discount 10625, bulk 1859 or 1860 = 12484 or 12485
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 12.5 }), 12484);
  // qty: 1, unitPrice: 1000, discount 50%: line total 1000, regular discount 500, no bulk (qty < 10) = 500
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 50 }), 500);
});

test('lineDiscount returns 0 when discountPercent is 0', () => {
  // qty: 100, unitPrice: 100, discount 0%: line total 10000, no regular discount, but bulk 250 applies
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 0 }), 250);
  // qty: 100, unitPrice: 100, no discount param: line total 10000, no regular discount, but bulk 250 applies
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100 }), 250);
});

test('lineDiscount returns 0 when qty is less than 10 and discountPercent is 0', () => {
  assert.equal(lineDiscount({ qty: 9, unitPrice: 100, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 9, unitPrice: 100 }), 0);
});

test('invoiceTotals calculates discount correctly with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, regular 8500, bulk on 76500 = 1912, total discount 10412
  // Line 2: 5 * 9500 = 47500, regular 9500, no bulk (qty < 10), total discount 9500
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 10412 + 9500);
  assert.equal(totals.total, 85000 + 47500 - 10412 - 9500);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 85000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals total greater than discount is calculated correctly', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 50, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line: 10 * 8500 = 85000, regular 50% = 42500, bulk on 42500 = 1062.5 ≈ 1062
  const regularDiscount = 42500;
  const bulkDiscount = Math.round(42500 * 2.5 / 100);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, regularDiscount + bulkDiscount);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 85000 - regularDiscount - bulkDiscount);
});

test('lineVat calculates VAT on amount after discount', () => {
  // qty: 100, unitPrice: 100: line total 10000, bulk 250, VAT on 9750 at 21% = 2047.5 ≈ 2048
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 21 }), 2048);
  // qty: 100, unitPrice: 100, discount 10%: line total 10000, regular 1000, bulk on 9000 = 225, VAT on 8775 at 21% = 1842.75 ≈ 1843
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }), 1843);
  // qty: 100, unitPrice: 100, discount 50%: line total 10000, regular 5000, bulk on 5000 = 125, VAT on 4875 at 21% = 1023.75 ≈ 1024
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 50, vatRate: 21 }), 1024);
});

test('lineVat handles different VAT rates', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 };
  // qty: 100, line total 100000, bulk 2500, remainder 97500
  // With vatRate 0: VAT on 97500 at 0% = 0
  assert.equal(lineVat({ ...line, vatRate: 0 }), 0);
  // With vatRate 9: VAT on 97500 at 9% = 8775
  assert.equal(lineVat({ ...line, vatRate: 9 }), 8775);
  // With vatRate 21: VAT on 97500 at 21% = 20475
  assert.equal(lineVat({ ...line, vatRate: 21 }), 20475);
});

test('lineVat returns 0 when vatRate is not provided', () => {
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 0 }), 0);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      { qty: 25, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 100 * 1000 = 100000, bulk 2500, VAT on 97500 at 21% = 20475
  // Line 2: 50 * 1000 = 50000, bulk 1250, VAT on 48750 at 9% = 4387.5 ≈ 4388
  // Line 3: 25 * 1000 = 25000, bulk 625, VAT on 24375 at 0% = 0
  const line1Discount = Math.round(100000 * 2.5 / 100);
  const line2Discount = Math.round(50000 * 2.5 / 100);
  const line3Discount = Math.round(25000 * 2.5 / 100);
  const line1Vat = Math.round((100000 - line1Discount) * 21 / 100);
  const line2Vat = Math.round((50000 - line2Discount) * 9 / 100);
  const line3Vat = 0;
  assert.equal(totals.subtotal, 100000 + 50000 + 25000);
  assert.equal(totals.discount, line1Discount + line2Discount + line3Discount);
  assert.equal(totals.vat, line1Vat + line2Vat + line3Vat);
  assert.equal(totals.total, 175000 - (line1Discount + line2Discount + line3Discount) + (line1Vat + line2Vat + line3Vat));
});

test('invoiceTotals VAT with discount and VAT on same line', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  const amountAfterDiscount = 100000 - 10000;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 100000 - 10000 + expectedVat);
});

