test('invoiceTotals total greater than discount is calculated correctly', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 50, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line: 10 * 8500 = 85000, regular 50% = 42500, bulk on 42500 = 1062.5 ≈ 1062
  const regularDiscount = 42500;
  const bulkDiscount = Math.round(42500 * 2.5 / 100);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, regularDiscount + bulkDiscount);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 85000 - regularDiscount - bulkDiscount);
});

test('lineVat calculates VAT on amount after discount', () => {
  // qty: 100, unitPrice: 100: line total 10000, bulk 250, VAT on 9750 at 21% = 2047.5 ≈ 2048
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 21 }), 2048);
  // qty: 100, unitPrice: 100, discount 10%: line total 10000, regular 1000, bulk on 9000 = 225, VAT on 8775 at 21% = 1842.75 ≈ 1843
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }), 1843);
  // qty: 100, unitPrice: 100, discount 50%: line total 10000, regular 5000, bulk on 5000 = 125, VAT on 4875 at 21% = 1023.75 ≈ 1024
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 50, vatRate: 21 }), 1024);
});

test('lineVat handles different VAT rates', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 };
  // qty: 100, line total 100000, bulk 2500, remainder 97500
  // With vatRate 0: VAT on 97500 at 0% = 0
  assert.equal(lineVat({ ...line, vatRate: 0 }), 0);
  // With vatRate 9: VAT on 97500 at 9% = 8775
  assert.equal(lineVat({ ...line, vatRate: 9 }), 8775);
  // With vatRate 21: VAT on 97500 at 21% = 20475
  assert.equal(lineVat({ ...line, vatRate: 21 }), 20475);
});

test('lineVat returns 0 when vatRate is not provided', () => {
