test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      { qty: 25, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 100 * 1000 = 100000, bulk 2500, VAT on 97500 at 21% = 20475
  // Line 2: 50 * 1000 = 50000, bulk 1250, VAT on 48750 at 9% = 4387.5 ≈ 4388
  // Line 3: 25 * 1000 = 25000, bulk 625, VAT on 24375 at 0% = 0
  const line1Discount = Math.round(100000 * 2.5 / 100);
  const line2Discount = Math.round(50000 * 2.5 / 100);
  const line3Discount = Math.round(25000 * 2.5 / 100);
  const line1Vat = Math.round((100000 - line1Discount) * 21 / 100);
  const line2Vat = Math.round((50000 - line2Discount) * 9 / 100);
  const line3Vat = 0;
  assert.equal(totals.subtotal, 100000 + 50000 + 25000);
  assert.equal(totals.discount, line1Discount + line2Discount + line3Discount);
  assert.equal(totals.vat, line1Vat + line2Vat + line3Vat);
  assert.equal(totals.total, 175000 - (line1Discount + line2Discount + line3Discount) + (line1Vat + line2Vat + line3Vat));
});

test('invoiceTotals VAT with discount and VAT on same line', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line: 100 * 1000 = 100000, regular 10% = 10000, bulk on 90000 = 2250, total discount 12250
  const lineTotal = 100000;
  const regularDiscount = 10000;
  const bulkDiscount = Math.round(90000 * 2.5 / 100);
  const amountAfterDiscount = lineTotal - regularDiscount - bulkDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, regularDiscount + bulkDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 100000 - regularDiscount - bulkDiscount + expectedVat);
});

