test('createInvoice EOM calculates last day of the month correctly', () => {
  const testCases = [
    { date: '2026-01-15', lastDay: '2026-01-31' },
    { date: '2026-02-10', lastDay: '2026-02-28' },
    { date: '2024-02-10', lastDay: '2024-02-29' },
    { date: '2026-04-10', lastDay: '2026-04-30' },
  ];
  for (const tc of testCases) {
    const r = createInvoice({
      customerId: 'C-002',
      issueDate: tc.date,
      lines: [{ sku: 'DES-HOUR', qty: 10 }],
      terms: 'EOM',
    });
    assert.equal(r.ok, true);
    assert.equal(r.value.dueDate, tc.lastDay, `for date ${tc.date}`);
  }
});

