  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10 },
      { qty: 5, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, regular 8500, bulk on 76500 = 1913, total discount 10413
  // Line 2: 5 * 9500 = 47500, regular 9500, no bulk (qty < 10), total discount 9500
  const line1Discount = 8500 + Math.round(76500 * 2.5 / 100);
  const line2Discount = 9500;
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, line1Discount + line2Discount);
  assert.equal(totals.total, 85000 + 47500 - line1Discount - line2Discount);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
