import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, lineDiscount, lineVat, invoiceTotals } from '../src/totals.js';

test('lineTotal returns qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 50 }), 100);
  assert.equal(lineTotal({ qty: 100, unitPrice: 1 }), 100);
});

test('lineTotal returns 0 for zero or negative totals', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 100 }), 0);
  assert.equal(lineTotal({ qty: -1, unitPrice: 100 }), 0);
});

test('lineDiscount calculates discount correctly', () => {
  // qty: 100, unitPrice: 100, discount 10%: line total 10000, regular 1000, bulk 225 = 1225
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 10 }), 1225);
  // qty: 10, unitPrice: 8500, discount 10%: line total 85000, regular 8500, bulk 1913 = 10413
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 10 }), 10413);
  // qty: 10, unitPrice: 8500, discount 12.5%: line total 85000, regular 10625, bulk 1859 = 12484
  assert.equal(lineDiscount({ qty: 10, unitPrice: 8500, discountPercent: 12.5 }), 12484);
  // qty: 1, unitPrice: 1000, discount 50%: line total 1000, regular 500, no bulk (qty < 10) = 500
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 50 }), 500);
});

test('lineDiscount returns 0 when discountPercent is 0', () => {
  // qty: 100, unitPrice: 100, discount 0%: line total 10000, no regular discount, but bulk 250 applies
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 0 }), 250);
  // qty: 100, unitPrice: 100, no discount param: line total 10000, no regular discount, but bulk 250 applies
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100 }), 250);
});

test('lineDiscount applies bulk discount for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0 };
  const lineTotal = 10 * 100; // 1000
  const bulkOnly = Math.round(1000 * 2.5 / 100); // 25
  assert.equal(lineDiscount(line), bulkOnly);
});

test('lineDiscount does not apply bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 100, discountPercent: 0 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount applies both regular and bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 10 };
  const lineTotal = 1000;
  const regularDiscount = Math.round(1000 * 10 / 100); // 100
  const amountAfterRegular = 1000 - 100; // 900
  const bulkDiscount = Math.round(900 * 2.5 / 100); // 22 (rounding 22.5)
  assert.equal(lineDiscount(line), regularDiscount + bulkDiscount);
});

test('lineDiscount bulk discount applies to amount after regular discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 50 };
  const lineTotal = 10000;
  const regularDiscount = 5000; // 50%
  const amountAfterRegular = 5000;
  const bulkDiscount = Math.round(5000 * 2.5 / 100); // 125
  assert.equal(lineDiscount(line), 5000 + 125);
});

test('lineDiscount bulk discount is 2.5% of remainder', () => {
  const line = { qty: 100, unitPrice: 100, discountPercent: 0 };
  const lineTotal = 10000;
  const bulkDiscount = Math.round(10000 * 2.5 / 100); // 250
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount with qty exactly 10 applies bulk discount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 40, discountPercent: 0 }), 10);
});

test('lineDiscount with qty 9 does not apply bulk discount', () => {
  assert.equal(lineDiscount({ qty: 9, unitPrice: 40, discountPercent: 0 }), 0);
});

test('lineDiscount returns 0 for negative totals', () => {
  assert.equal(lineDiscount({ qty: -1, unitPrice: 100, discountPercent: 10 }), 0);
});

test('lineVat calculates VAT on amount after discount', () => {
  // qty: 100, unitPrice: 100: line total 10000, bulk 250, VAT on 9750 at 21% = 2047.5 ≈ 2048
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 21 }), 2048);
  // qty: 100, unitPrice: 100, discount 10%: line total 10000, regular 1000, bulk on 9000 = 225, VAT on 8775 at 21% = 1842.75 ≈ 1843
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }), 1843);
  // qty: 100, unitPrice: 100, discount 50%: line total 10000, regular 5000, bulk on 5000 = 125, VAT on 4875 at 21% = 1023.75 ≈ 1024
  assert.equal(lineVat({ qty: 100, unitPrice: 100, discountPercent: 50, vatRate: 21 }), 1024);
});

test('lineVat handles different VAT rates', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 };
  // qty: 100, line total 100000, bulk 2500, remainder 97500
  // With vatRate 0: VAT on 97500 at 0% = 0
  assert.equal(lineVat({ ...line, vatRate: 0 }), 0);
  // With vatRate 9: VAT on 97500 at 9% = 8775
  assert.equal(lineVat({ ...line, vatRate: 9 }), 8775);
  // With vatRate 21: VAT on 97500 at 21% = 20475
  assert.equal(lineVat({ ...line, vatRate: 21 }), 20475);
